#!/usr/bin/env bash
# Run on the Jemasa collector appliance AFTER it shows v0.7.0 in SPARK.
# Installs the local RDP/VNC/Telnet engine (guacd, loopback only). It does not
# touch enrolment, firewall or the collector container. SSH terminals and
# device web pages work without it; only browser desktops (RDP/VNC) need it.
set -euo pipefail
[[ $EUID -eq 0 ]] || { echo 'Run as root (sudo -i first).' >&2; exit 1; }
d="$(mktemp -d)"; trap 'rm -rf "$d"' EXIT
echo '' | base64 -d | tar -C "$d" -xzf -
bash "$d/install-local-remote.sh"
